import Foundation

/// Small real images for the DEVELOPMENT store only.
///
/// The seeded chat photos used to be `sim://` placeholders, which have no file
/// behind them — so nothing in development could prove a chat photo actually
/// opens full size. These are tiny 240×160 PNGs held as `data:` references,
/// the same inline form a real photo takes when it is stored with the record,
/// so the viewer decodes them exactly as it would in production.
///
/// Never used by the production gateway.
nonisolated enum DevSeedImages {
    /// Engineer → office, job J-1042 (also that job's evidence).
    static let condenser = "data:image/png;base64,"

    /// Engineer → office, general conversation (no job).
    static let depotBays = "data:image/png;base64,"

    /// Office → engineer, job J-1042 (also that job's evidence).
    static let replacementPart = "data:image/png;base64,"

    /// Office → engineer, general conversation (no job).
    static let depotLayout = "data:image/png;base64,"
}
